-- GMI price-list references converted to provisional modal estimates:
-- GMI list price includes 11% PPN; estimate = (listed unit price / 1.11) / 1.20, HALF_UP to 2 decimals.
-- SINY entries use the supplier's tax-inclusive January 2024 prices and are marked for verification.
-- On conflict, fill only missing purchase_price values; preserve existing non-NULL modal and category.
begin;
on conflict (sku) do update set
 name=excluded.name, brand=excluded.brand, variant=excluded.variant,
 category=case when public.products.purchase_price is null then excluded.category else public.products.category end,
 unit=excluded.unit,
 purchase_price=coalesce(public.products.purchase_price,excluded.purchase_price),
 list_price_source=excluded.list_price_source, pack_quantity=excluded.pack_quantity;
commit;
